def merge_k_lists(lists):
    merged = []
    for values in lists:
        merged.extend(values)                                              # collect every value from every list
    merged.sort()                                                          # sort everything together
    return merged


if __name__ == "__main__":
    print(merge_k_lists([[1, 4, 5], [1, 3, 4], [2, 6]]))

