import java.util.*;

public class Main {
    List<Integer> mergeKLists(List<List<Integer>> lists) {
        List<Integer> merged = new ArrayList<>();
        for (List<Integer> values : lists) merged.addAll(values);                   // collect every value from every list
        Collections.sort(merged);                                                     // sort everything together
        return merged;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        List<List<Integer>> lists = Arrays.asList(Arrays.asList(1, 4, 5), Arrays.asList(1, 3, 4), Arrays.asList(2, 6));
        System.out.println(solution.mergeKLists(lists));
    }
}

