#include <bits/stdc++.h>
using namespace std;

vector<int> mergeKLists(vector<vector<int>>& lists) {
    vector<int> merged;
    for (auto& values : lists) {
        merged.insert(merged.end(), values.begin(), values.end());                  // collect every value from every list
    }
    sort(merged.begin(), merged.end());                                              // sort everything together
    return merged;
}

int main() {
    vector<vector<int>> lists = {{1, 4, 5}, {1, 3, 4}, {2, 6}};
    vector<int> result = mergeKLists(lists);
    for (int v : result) cout << v << " ";
    cout << endl;
    return 0;
}

