import java.util.*;

public class Main {
    ListNode mergeKLists(ListNode[] lists) {
        PriorityQueue<ListNode> heap = new PriorityQueue<>((a, b) -> a.val - b.val);
        for (ListNode node : lists) {
            if (node != null) heap.offer(node);                                        // seed the heap with every list's head
        }

        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        while (!heap.isEmpty()) {
            ListNode node = heap.poll();                                                  // always pop the CURRENT smallest front node across all lists
            tail.next = node;
            tail = node;
            if (node.next != null) heap.offer(node.next);                                 // push that same list's next node back in
        }
        tail.next = null;
        return dummy.next;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode[] lists = {
            new ListNode(1, new ListNode(4, new ListNode(5))),
            new ListNode(1, new ListNode(3, new ListNode(4))),
            new ListNode(2, new ListNode(6)),
        };
        ListNode result = solution.mergeKLists(lists);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

