#include <bits/stdc++.h>
using namespace std;

ListNode* mergeKLists(vector<ListNode*>& lists) {
    auto cmp = [](ListNode* a, ListNode* b) { return a->val > b->val; };
    priority_queue<ListNode*, vector<ListNode*>, decltype(cmp)> heap(cmp);
    for (ListNode* node : lists) {
        if (node) heap.push(node);                                                       // seed the heap with every list's head
    }

    ListNode dummy(0);
    ListNode* tail = &dummy;
    while (!heap.empty()) {
        ListNode* node = heap.top(); heap.pop();                                            // always pop the CURRENT smallest front node across all lists
        tail->next = node;
        tail = node;
        if (node->next) heap.push(node->next);                                                // push that same list's next node back in
    }
    tail->next = nullptr;
    return dummy.next;
}

int main() {
    vector<ListNode*> lists = {
        new ListNode(1, new ListNode(4, new ListNode(5))),
        new ListNode(1, new ListNode(3, new ListNode(4))),
        new ListNode(2, new ListNode(6)),
    };
    ListNode* result = mergeKLists(lists);
    while (result) { cout << result->val << " "; result = result->next; }
    cout << endl;
    return 0;
}
